const { Sequelize, DataTypes } = require('sequelize');
const fs = require('fs');
const path = require('path');

const TRANSITIONS = {
  pending: ['cancelled', 'paid'],
  paid: ['cancelled', 'shipped'],
  shipped: ['delivered'],
  delivered: [],
  cancelled: []
};

function initDb(dbPath) {
  // Ensure parent directory exists
  const resolvedPath = path.resolve(dbPath);
  const dbDir = path.dirname(resolvedPath);
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }

  const sequelize = new Sequelize({
    dialect: 'sqlite',
    storage: resolvedPath,
    logging: false,
    dialectOptions: {
      timeout: 10000 // 10s busy timeout for SQLite concurrency
    }
  });

  const Order = sequelize.define('Order', {
    id: {
      type: DataTypes.INTEGER,
      primaryKey: true,
      autoIncrement: true
    },
    status: {
      type: DataTypes.STRING,
      allowNull: false,
      defaultValue: 'pending',
      validate: {
        isIn: [['pending', 'paid', 'shipped', 'delivered', 'cancelled']]
      }
    }
  }, {
    timestamps: true
  });

  const OrderStatusHistory = sequelize.define('OrderStatusHistory', {
    id: {
      type: DataTypes.INTEGER,
      primaryKey: true,
      autoIncrement: true
    },
    orderId: {
      type: DataTypes.INTEGER,
      allowNull: false
    },
    fromStatus: {
      type: DataTypes.STRING,
      allowNull: false
    },
    toStatus: {
      type: DataTypes.STRING,
      allowNull: false
    },
    at: {
      type: DataTypes.DATE,
      allowNull: false,
      defaultValue: DataTypes.NOW
    }
  }, {
    timestamps: false,
    tableName: 'OrderStatusHistories'
  });

  // Associations
  Order.hasMany(OrderStatusHistory, { foreignKey: 'orderId', as: 'history' });
  OrderStatusHistory.belongsTo(Order, { foreignKey: 'orderId' });

  // Model-level transition logic
  Order.prototype.transitionTo = async function(toStatus, transaction) {
    const fromStatus = this.status;
    const allowed = TRANSITIONS[fromStatus];
    if (!allowed || !allowed.includes(toStatus)) {
      const err = new Error('ILLEGAL_TRANSITION');
      err.name = 'IllegalTransitionError';
      err.from = fromStatus;
      err.to = toStatus;
      throw err;
    }

    this.status = toStatus;
    await this.save({ transaction });

    await OrderStatusHistory.create({
      orderId: this.id,
      fromStatus,
      toStatus,
      at: new Date()
    }, { transaction });
  };

  return { sequelize, Order, OrderStatusHistory };
}

module.exports = {
  TRANSITIONS,
  initDb
};

#!/usr/bin/env node
const { initDb, TRANSITIONS } = require('./db');
const { Transaction } = require('sequelize');

function parseArgs() {
  const args = process.argv.slice(2);
  const subcommand = args[0];

  const options = {};
  for (let i = 1; i < args.length; i++) {
    if (args[i].startsWith('--')) {
      const key = args[i].slice(2);
      const val = args[i + 1];
      if (val !== undefined && !val.startsWith('--')) {
        options[key] = val;
        i++;
      } else {
        options[key] = true;
      }
    }
  }

  return { subcommand, options };
}

async function main() {
  const { subcommand, options } = parseArgs();

  if (!subcommand) {
    console.error('Error: Subcommand is required.');
    process.exit(1);
  }

  const dbPath = options.db;
  if (!dbPath) {
    console.error('Error: --db <path> is required.');
    process.exit(1);
  }

  // Initialize DB and ensure schema exists
  const { sequelize, Order, OrderStatusHistory } = initDb(dbPath);
  try {
    await sequelize.sync();
  } catch (error) {
    console.error('Error ensuring schema exists:', error);
    process.exit(1);
  }

  if (subcommand === 'init') {
    console.log(JSON.stringify({ ok: true }));
    await sequelize.close();
    process.exit(0);
  }

  if (subcommand === 'create') {
    try {
      const order = await Order.create({ status: 'pending' });
      console.log(JSON.stringify({ id: order.id, status: 'pending' }));
      await sequelize.close();
      process.exit(0);
    } catch (error) {
      console.error('Error creating order:', error);
      await sequelize.close();
      process.exit(1);
    }
  }

  if (subcommand === 'transition') {
    const orderIdStr = options.id;
    const toStatus = options.to;

    if (!orderIdStr) {
      console.error('Error: --id <number> is required.');
      await sequelize.close();
      process.exit(1);
    }
    if (!toStatus) {
      console.error('Error: --to <status> is required.');
      await sequelize.close();
      process.exit(1);
    }

    const orderId = parseInt(orderIdStr, 10);
    if (isNaN(orderId)) {
      console.error('Error: --id must be a valid number.');
      await sequelize.close();
      process.exit(1);
    }

    try {
      let result;
      await sequelize.transaction({ type: Transaction.TYPES.IMMEDIATE }, async (t) => {
        const order = await Order.findByPk(orderId, { transaction: t });
        if (!order) {
          const err = new Error('NOT_FOUND');
          err.name = 'NotFoundError';
          throw err;
        }

        const from = order.status;
        await order.transitionTo(toStatus, t);

        result = {
          ok: true,
          id: order.id,
          from,
          to: toStatus
        };
      });

      console.log(JSON.stringify(result));
      await sequelize.close();
      process.exit(0);
    } catch (error) {
      if (error.name === 'NotFoundError') {
        console.log(JSON.stringify({
          ok: false,
          error: 'NOT_FOUND',
          id: orderId
        }));
        await sequelize.close();
        process.exit(4);
      } else if (error.name === 'IllegalTransitionError') {
        console.log(JSON.stringify({
          ok: false,
          error: 'ILLEGAL_TRANSITION',
          id: orderId,
          from: error.from,
          to: error.to
        }));
        await sequelize.close();
        process.exit(3);
      } else {
        console.error('Error executing transition:', error);
        await sequelize.close();
        process.exit(1);
      }
    }
  }

  if (subcommand === 'show') {
    const orderIdStr = options.id;
    if (!orderIdStr) {
      console.error('Error: --id <number> is required.');
      await sequelize.close();
      process.exit(1);
    }

    const orderId = parseInt(orderIdStr, 10);
    if (isNaN(orderId)) {
      console.error('Error: --id must be a valid number.');
      await sequelize.close();
      process.exit(1);
    }

    try {
      const order = await Order.findByPk(orderId, {
        include: [{
          model: OrderStatusHistory,
          as: 'history'
        }]
      });

      if (!order) {
        console.log(JSON.stringify({
          ok: false,
          error: 'NOT_FOUND',
          id: orderId
        }));
        await sequelize.close();
        process.exit(4);
      }

      const history = (order.history || [])
        .sort((a, b) => a.id - b.id)
        .map(h => ({
          fromStatus: h.fromStatus,
          toStatus: h.toStatus,
          at: h.at instanceof Date ? h.at.toISOString() : new Date(h.at).toISOString()
        }));

      console.log(JSON.stringify({
        id: order.id,
        status: order.status,
        history
      }));

      await sequelize.close();
      process.exit(0);
    } catch (error) {
      console.error('Error showing order:', error);
      await sequelize.close();
      process.exit(1);
    }
  }

  if (subcommand === 'transitions') {
    // Print transition table
    console.log(JSON.stringify(TRANSITIONS));
    await sequelize.close();
    process.exit(0);
  }

  console.error(`Error: Unknown subcommand "${subcommand}"`);
  await sequelize.close();
  process.exit(1);
}

main().catch(async (error) => {
  console.error('Unhandled error in main:', error);
  process.exit(1);
});

const { execSync, exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const dbPath = path.join(__dirname, 'concurrency_test.db');

// Clean up previous test DB
if (fs.existsSync(dbPath)) {
  fs.unlinkSync(dbPath);
}

// 1. Init
console.log('Initializing DB...');
execSync(`node cli.js init --db ${dbPath}`);

// 2. Create order
console.log('Creating order...');
const createOutput = execSync(`node cli.js create --db ${dbPath}`).toString();
const order = JSON.parse(createOutput);
console.log('Created order:', order);

// 3. Transition to paid
console.log('Transitioning to paid...');
execSync(`node cli.js transition --db ${dbPath} --id ${order.id} --to paid`);

// 4. Run concurrent transitions: one to shipped, one to cancelled
console.log('Running concurrent transitions from paid to shipped and cancelled...');

function runTransition(toStatus) {
  return new Promise((resolve) => {
    exec(`node cli.js transition --db ${dbPath} --id ${order.id} --to ${toStatus}`, (error, stdout, stderr) => {
      resolve({
        toStatus,
        code: error ? error.code : 0,
        stdout: stdout.trim(),
        stderr: stderr.trim()
      });
    });
  });
}

async function run() {
  const results = await Promise.all([
    runTransition('shipped'),
    runTransition('cancelled')
  ]);

  console.log('Results:', results);

  // One should succeed (exit code 0) and the other should fail (exit code 3)
  const successes = results.filter(r => r.code === 0);
  const failures = results.filter(r => r.code === 3);

  console.log(`Successes: ${successes.length}`);
  console.log(`Failures: ${failures.length}`);

  if (successes.length === 1 && failures.length === 1) {
    console.log('PASS: Exactly one transition succeeded, and the other failed with exit code 3!');
  } else {
    console.error('FAIL: Concurrency constraint violated!');
    process.exit(1);
  }

  // Show order status and history
  const showOutput = execSync(`node cli.js show --db ${dbPath} --id ${order.id}`).toString();
  console.log('Final Order State:', showOutput);

  // Clean up
  if (fs.existsSync(dbPath)) {
    fs.unlinkSync(dbPath);
  }
}

run();

